def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    from collections import Counter
    counts = Counter(v for row in g for v in row)
    bg = counts.most_common(1)[0][0]

    # The non-background colors on the two extreme rows are the end bars.
    bars = []
    for r in (0, h - 1):
        c = 0
        while c < w:
            v = g[r][c]
            e = c + 1
            while e < w and g[r][e] == v:
                e += 1
            if v != bg and e - c > 1:
                bars.append((r, c, e, v))
            c = e
    if len(bars) < 2:
        return g

    bar_colors = {b[3] for b in bars}
    markers = [(r, c, v) for r in range(h) for c, v in enumerate(g[r])
               if v != bg and v not in bar_colors]
    if not markers:
        return g
    marker_color = Counter(v for _, _, v in markers).most_common(1)[0][0]
    marker_cols = [c for _, c, v in markers if v == marker_color]
    width = len(marker_cols)
    # Each bar paints the rightmost marker-count cells of its horizontal run.
    for r, c0, c1, _ in bars:
        start = c1 - width
        dr = 1 if r == 0 else -1
        rr = r + dr
        while 0 <= rr < h:
            for c in range(start, start + width):
                if g[rr][c] == marker_color:
                    g[rr][c] = 4
                else:
                    g[rr][c] = marker_color
            rr += dr
    return g
